import{_ as s,c as t,a2 as a,o as e}from"./chunks/framework.CqbvlPrP.js";const _="/assets/1.DViievcT.jpg",o="/assets/2.CLF3gOnC.jpg",r="/assets/3.O4kqJDIx.jpg",c="/assets/4.C3b0L0SP.jpg",i="/assets/5.BHTq76Sv.jpg",m="/assets/6.Zn1R8mrF.jpg",n="/assets/7.ZZziyML4.jpg",l="/assets/8.CxVNxXzu.jpg",k=JSON.parse('{"title":"胜率和盈亏比，决定不了交易系统的获利能力","description":"","frontmatter":{},"headers":[],"relativePath":"stock/盈亏比/胜率和盈亏比，决定不了交易系统的获利能力.md","filePath":"stock/盈亏比/胜率和盈亏比，决定不了交易系统的获利能力.md"}'),g={name:"stock/盈亏比/胜率和盈亏比，决定不了交易系统的获利能力.md"};function d(B,p,f,A,j,u){return e(),t("div",null,p[0]||(p[0]=[a('<h1 id="胜率和盈亏比-决定不了交易系统的获利能力" tabindex="-1">胜率和盈亏比，决定不了交易系统的获利能力 <a class="header-anchor" href="#胜率和盈亏比-决定不了交易系统的获利能力" aria-label="Permalink to &quot;胜率和盈亏比，决定不了交易系统的获利能力&quot;">​</a></h1><p>天启大烁哥</p><p>交易最终能否获利，需要你的胜率和盈亏比有正期望。但是，交易最终能够获利多少，是由你的胜率和盈亏比，以及你的风险暴露程度两者，共同决定。</p><p>最近我的很多客户问我胜率和盈亏比的问题。今天，系统的帮助各位缕一下逻辑。</p><p>首先，第一个非常简单。</p><p>交易最终能够获利，需要你在进行了大量的长期交易之后，你的胜率和盈亏比有数学上的概率优势。</p><p>怎么计算？</p><p>比如，你的胜率是60%，盈亏比2比1。那么算法就是，0.6<em>2-0.4</em>1=0.8。最终，只要这个数是个正数，你就有正期望。</p><p>再比如，你胜率70%，盈亏比1比3。那么算法就是，0.7<em>1-0.3</em>3=-0.2。结果为负，这样你的交易系统就是负期望的。你长期交易下去，必亏无疑。</p><p>所以，单看胜率，没什么用。</p><p>好，现在，我们假设有两个系统。10年交易下来综合计算：</p><p>A系统，胜率80%盈亏比10比1。</p><p>B系统，胜率50%盈亏比2比1。</p><p>那么，问题来了，你说胜率和盈亏比都高的那个系统，一定获利更多吗？</p><p>答案是，不一定。</p><p>为什么？开头我给了答案，你最终能够获利多少的，不是由胜率和盈亏比单独决定的。而是由，胜率和盈亏比，以及风险暴露程度，共同决定的。</p><p>首先，在过去的10年里，A系统仅交易了100次，而B系统交易了10000次。这种情况下，你的最终收益敢说肯定比他多吗？</p><p>这是交易频率的不同。</p><p>其次，假设A系统在过去的10年里，交易了10000次，B也交易了10000次，但是，A一次仅开1手，B一次开100手。你敢说A赚的一定比B多？</p><p>这是交易仓位的不同。</p><p>还有，A在过去的10年里，交易了10000次，B也交易了10000次，而且，A一次开1手，B一次也开1手，但是，A的盈亏比由来是，平均盈利2万/平均亏损1万，而B的盈亏比由来是：平均盈利1000/平均亏损100。A能赚过B吗？不能。</p><p>这是交易级别的不同。</p><p>交易频率，交易仓位，和交易级别，综合起来，就是风险敞口的暴露程度。这是决定了你最终盈利的另一个关键核心，而胜率和盈亏比，仅是用来描述你交易逻辑的特征而已。</p><p>好了，明白了这点，我们来研究一个问题，就是一个交易员到底该如何去设置自己的胜率和盈亏比呢？</p><p>一般来说，对于一个交易员而言，胜率和盈亏比我觉得根本不用刻意去定一个数值，这个不应该是关注的重点。因为从本质而言，它们仅是我们进出场规则背后附带的一个特征而已。</p><p>我们应该关注的，是自己到底该用什么样的节奏去进场和出场。</p><p>这是核心。</p><p>举个例子，比如有的人利用均线做交易系统。他的出场规则依据很多，其中模式之一就是均线。</p><p>那么，很明显，均线的数值选的越大，承担的回撤空间就越大，所以，他的交易级别就会越大。</p><p>10日均线：</p><p><img src="'+_+'" alt="图片"></p><p>20日均线：</p><p><img src="'+o+'" alt="图片"></p><p>40日均线​：</p><p><img src="'+r+'" alt="图片"></p><p>60日均线​：</p><p><img src="'+c+'" alt="图片"></p><p>而一般来说，交易级别越大，胜率就会越低，而盈亏比就会越高。</p><p>在这里，我分别用了10，20，40，60条线做了测试。</p><p>结果也确实如此。</p><p><img src="'+i+'" alt="图片"><img src="'+m+'" alt="图片"><img src="'+n+'" alt="图片"><img src="'+l+'" alt="图片"></p><p>所以在这里，你重点需要去观察整个交易过程，你最偏好的是哪个？选定了那个过程，你自然就选定了那个过程所自带的，胜率和盈亏比。</p><p>这就是我建议的选法。通过量化的模式，大量的观察自己选定系统的交易过程，对各个数值它的特征，都会有一定的整体了解。</p><p>当然了，也有一些交易者，可能是因为他们不会量化，或者说他们有其他偏好，总之，他们并不是先定系统，然后附带盈亏比，他们是围绕胜率和盈亏比来定出入场。</p><p>比如，有的人就想要把盈亏比定在1比1左右，因为他知道，​降低盈亏比，相应的胜率就会提高。​而他喜欢胜率高的感觉。</p><p>​这种也是可以的。毕竟，只要胜率和盈亏比长期统计下来，有正期望就可以。盈亏比1比1，胜率超过50%，​理论上依然具备正期望。</p><p>只不过，你需要关注一下自己的试错效率。</p><p>比如，出场方面，可以让利润奔跑。止损1万，盈利到1万的时候不要直接落袋，可以设置一个浮动回撤出场。这样的话，你还可以顺着方向再冲一冲，这种调整，综合来看，是可以提高试错效率的。</p><p>好了，总结而言，胜率和盈亏比，是出入场决定的交易逻辑的一个特征。它能决定你是否有正期望，但是它并不能决定你最终获利的多少，最终获利，由交易逻辑和你的风险暴露程度综合决定。</p><p>所以，评估获利能力，要看交易系统的全貌。</p>',50)]))}const x=s(g,[["render",d]]);export{k as __pageData,x as default};
